.cn-flow-tab__banner[data-v-65fa2c21] {
	display: flex;
	align-items: center;
	gap: 8px;
	padding: 8px 10px;
	margin-bottom: 10px;
	border-radius: var(--border-radius);
	background: var(--color-warning, #e9a40f);
	color: var(--color-main-background);
	font-size: 0.9em;
}
.cn-flow-tab__actions[data-v-65fa2c21] {
	margin-bottom: 8px;
}
.cn-flow-tab__error[data-v-65fa2c21] {
	color: var(--color-error);
	font-size: 0.9em;
	margin: 4px 0 8px;
}
.cn-flow-tab__empty[data-v-65fa2c21] {
	display: flex;
	flex-direction: column;
	align-items: center;
	gap: 8px;
	padding: 16px 8px;
	color: var(--color-text-maxcontrast);
	text-align: center;
}
.cn-flow-tab__empty-icon[data-v-65fa2c21] {
	color: var(--color-text-maxcontrast);
}
.cn-flow-tab__list[data-v-65fa2c21] {
	list-style: none;
	margin: 0;
	padding: 0;
}

/* Mirror NC Flow's rule rows: a round robot avatar, the bold rule
   name, a trigger/condition subline, and an enabled/disabled chip. */
.cn-flow-tab__row--disabled[data-v-65fa2c21] {
	opacity: 0.7;
}
.cn-flow-tab__avatar[data-v-65fa2c21] {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 36px;
	height: 36px;
	border-radius: 50%;
	background: var(--color-background-dark);
	color: var(--color-text-maxcontrast);
	flex-shrink: 0;
}
.cn-flow-tab__avatar.cn-flow-tab__enabled--on[data-v-65fa2c21] {
	background: var(--color-primary-element-light, var(--color-background-dark));
	color: var(--color-primary-element, #0082c9);
}
.cn-flow-tab__avatar.cn-flow-tab__enabled--off[data-v-65fa2c21] {
	background: var(--color-background-dark);
	color: var(--color-text-maxcontrast);
}
.cn-flow-tab__summary[data-v-65fa2c21] {
	font-size: 0.85em;
	color: var(--color-text-maxcontrast);
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}
.cn-flow-tab__meta[data-v-65fa2c21] {
	font-size: 0.8em;
	color: var(--color-text-maxcontrast);
}
.cn-flow-tab__details[data-v-65fa2c21] {
	display: inline-flex;
	align-items: center;
	flex-wrap: wrap;
	gap: 6px;
}
.cn-flow-tab__events[data-v-65fa2c21] {
	display: inline-flex;
	flex-wrap: wrap;
	gap: 4px;
}
.cn-flow-tab__chip[data-v-65fa2c21] {
	display: inline-block;
	padding: 1px 8px;
	border-radius: 10px;
	background: var(--color-background-hover);
	color: var(--color-main-text);
	font-size: 0.75em;
}
