  border-bottom: 1px solid var(--color-border);
}
.tabContainer > * ul[role="tablist"] > * a[role="tab"][data-v-30c7109c] {
  padding-inline-start: 10px;
  padding-inline-end: 10px;
  padding-block-start: 10px;
  padding-block-end: 10px;
}
.tabContainer > * div[role="tabpanel"][data-v-30c7109c] {
  margin-block-start: var(--OR-margin-10);
}
[data-v-30c7109c] .nav-tabs {
	border-bottom: 1px solid var(--color-border);
	margin-bottom: 15px;
	display: flex;
}
[data-v-30c7109c] .nav-tabs .nav-item {
	display: flex;
	flex: 1;
}
[data-v-30c7109c] .nav-tabs .nav-link {
	flex: 1;
	text-align: center;
	border: none;
	border-bottom: 2px solid transparent;
	color: var(--color-text-maxcontrast);
	padding: 8px 16px;
}
[data-v-30c7109c] .nav-tabs .nav-link.active {
	color: var(--color-main-text);
	border-bottom: 2px solid var(--color-primary);
	background-color: transparent;
}
[data-v-30c7109c] .nav-tabs .nav-link:hover {
	border-bottom: 2px solid var(--color-border);
}
[data-v-30c7109c] .tab-content {
	padding: 16px;
	background-color: var(--color-main-background);
}

/* Hand-rolled tab nav — replaces bootstrap-vue's BTabs/BTab. */
