	display: flex;
	gap: 0;
	list-style: none;
	padding: 0;
	margin: 0 0 16px;
	border-bottom: 1px solid var(--color-border);
}
.cn-advanced-form-dialog__tab-nav-item[data-v-30c7109c] {
	flex: 1 1 0;
}
.cn-advanced-form-dialog__tab-button[data-v-30c7109c] {
