}
.cn-advanced-form-dialog__tab-button[data-v-30c7109c]:disabled {
	opacity: 0.5;
	cursor: not-allowed;
}
.cn-advanced-form-dialog__tab-content[data-v-30c7109c] {
	padding: 16px 0;
}
