.cn-forms-tab[data-v-a75a5f66] {
	padding: 12px;
}
.cn-forms-tab__header[data-v-a75a5f66] {
	display: flex;
	gap: 8px;
	justify-content: flex-end;
	margin-bottom: 10px;
	flex-wrap: wrap;
}
.cn-forms-tab__banner[data-v-a75a5f66] {
	display: flex;
	align-items: center;
	gap: 8px;
	padding: 8px 10px;
	margin-bottom: 10px;
	border-radius: var(--border-radius);
	background: var(--color-warning, #e9a40f);
	color: var(--color-main-background);
	font-size: 0.9em;
}
.cn-forms-tab__error[data-v-a75a5f66] {
	color: var(--color-error);
	font-size: 0.9em;
	margin: 4px 0 8px;
}
.cn-forms-tab__empty[data-v-a75a5f66] {
	display: flex;
	flex-direction: column;
	align-items: center;
	gap: 8px;
	padding: 16px 8px;
	color: var(--color-text-maxcontrast);
	text-align: center;
}
.cn-forms-tab__empty-icon[data-v-a75a5f66] {
	color: var(--color-text-maxcontrast);
}
.cn-forms-tab__list[data-v-a75a5f66] {
	list-style: none;
	margin: 0;
	padding: 0;
}

/* Forms brand accent on the row icon, mirroring the real Forms app. */
.cn-forms-tab__row-icon[data-v-a75a5f66] {
	color: var(--cn-forms-accent, #0d7000);
	flex-shrink: 0;
}
.cn-forms-tab__row--closed[data-v-a75a5f66] {
	opacity: 0.85;
}
.cn-forms-tab__row--closed .cn-forms-tab__row-icon[data-v-a75a5f66] {
	color: var(--color-text-maxcontrast);
}
.cn-forms-tab__description[data-v-a75a5f66] {
	display: -webkit-box;
	-webkit-line-clamp: 2;
	-webkit-box-orient: vertical;
	overflow: hidden;
	color: var(--color-text-maxcontrast);
}
.cn-forms-tab__details[data-v-a75a5f66] {
	display: flex;
	align-items: center;
	gap: 6px;
	flex-wrap: wrap;
	justify-content: flex-end;
}
.cn-forms-tab__expiry[data-v-a75a5f66] {
	font-size: 0.8em;
	color: var(--color-text-maxcontrast);
	white-space: nowrap;
}

